mapper.select:
SELECT * FROM (
    SELECT a.*, ROWNUM rnum
    FROM (
        SELECT faq_id, category, question, answer, writer, created_at, updated_at
        FROM faq
        ORDER BY faq_id
    ) a
    WHERE ROWNUM <= #{endRow,jdbcType=INTEGER}
)
WHERE rnum >= #{startRow,jdbcType=INTEGER}

SELECT * FROM (
    SELECT a.*, ROWNUM rnum
    FROM (
        SELECT faq_id, category, question, answer, writer, created_at, updated_at
        FROM faq
        WHERE category = #{category,jdbcType=VARCHAR}
        ORDER BY faq_id
    ) a
    WHERE ROWNUM <= #{endRow,jdbcType=INTEGER}
)
WHERE rnum >= #{startRow,jdbcType=INTEGER}

SELECT * FROM (
    SELECT a.*, ROWNUM rnum
    FROM (
        SELECT faq_id, category, question, answer, writer, created_at, updated_at
        FROM faq
        WHERE LOWER(question) LIKE '%' || LOWER(#{keyword,jdbcType=VARCHAR}) || '%'
           OR LOWER(answer) LIKE '%' || LOWER(#{keyword,jdbcType=VARCHAR}) || '%'
        ORDER BY faq_id
    ) a
    WHERE ROWNUM <= #{endRow,jdbcType=INTEGER}
)
WHERE rnum >= #{startRow,jdbcType=INTEGER}

SELECT * FROM (
    SELECT a.*, ROWNUM rnum
    FROM (
        SELECT faq_id, category, question, answer, writer, created_at, updated_at
        FROM faq
        WHERE 1=1

            AND category = #{category}


            AND (LOWER(question) LIKE '%' || LOWER(#{keyword}) || '%' 
              OR LOWER(answer) LIKE '%' || LOWER(#{keyword}) || '%')


            AND writer = #{writer}


            AND created_at >= TO_DATE(#{fromDate}, 'YYYY-MM-DD')


            AND created_at <= TO_DATE(#{toDate}, 'YYYY-MM-DD')

        ORDER BY faq_id
    ) a
    WHERE ROWNUM <= #{endRow}
)
WHERE rnum >= #{startRow}

SELECT COUNT(*) FROM faq WHERE 1=1
AND category = #{category}
AND (LOWER(question) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(answer) LIKE '%' || LOWER(#{keyword}) || '%')
AND writer = #{writer}
AND created_at >= TO_DATE(#{fromDate}, 'YYYY-MM-DD')
AND created_at <= TO_DATE(#{toDate}, 'YYYY-MM-DD')

SELECT FAQ_ID, CATEGORY, QUESTION, ANSWER, WRITER, CREATED_AT, UPDATED_AT
FROM FAQ
WHERE FAQ_ID = #{id}
